    private void setupDomains(){domainColors.put("القرآن",GREEN);domainColors.put("الطب والقبول",CYAN);domainColors.put("الإنجليزية",BLUE);domainColors.put("العمل والدخل",ORANGE);domainColors.put("الصحة",RED);domainColors.put("المعرفة والقراءة",PURPLE);domainColors.put("التواصل",TEAL);domainColors.put("الأسرة",PINK);domainColors.put("الدين والمسجد",Color.rgb(64,133,83));domainColors.put("الانضباط",Color.rgb(102,113,126));domainColors.put("الراحة",REST);}

    private void migrateV16(){if(prefs.getBoolean("v16_migrated",false))return;SharedPreferences.Editor e=prefs.edit();int old=prefs.getInt("reward_domain_الإنجليزية والقبول",0),now=prefs.getInt("reward_domain_الإنجليزية",0);if(old>0&&now==0)e.putInt("reward_domain_الإنجليزية",old);e.putBoolean("v16_migrated",true);e.apply();}

    private void render(){if(currentScroll!=null)scrollY.put(tab,currentScroll.getScrollY());LinearLayout shell=new LinearLayout(this);shell.setOrientation(LinearLayout.VERTICAL);shell.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);shell.setBackgroundColor(BG);FrameLayout body=new FrameLayout(this);shell.addView(body,new LinearLayout.LayoutParams(-1,0,1));View page;switch(tab){case"tasks":page=tasksPage();break;case"stats":page=statsPage();break;case"rewards":page=rewardsPage();break;case"more":page=morePage();break;default:page=homePage();}body.addView(page,new FrameLayout.LayoutParams(-1,-1));shell.addView(bottomNav(),new LinearLayout.LayoutParams(-1,dp(72)));setContentView(shell);if(page instanceof ScrollView){currentScroll=(ScrollView)page;int y=scrollY.containsKey(tab)?scrollY.get(tab):0;currentScroll.post(()->currentScroll.scrollTo(0,y));}else currentScroll=null;}

