    private void addDayModeBanner(LinearLayout r){Calendar c=Calendar.getInstance();if(!isThursday(c)&&!isFriday(c)&&!rescueActiveToday())return;LinearLayout b=card();b.setPadding(dp(10),dp(9),dp(10),dp(9));add(r,b,7);LinearLayout rr=row();String icon,title,sub;int col;if(isFriday(c)){icon="rest";title="يوم الراحة";sub="اليوم لا يُحسب عليك تقصير، ولا يكسر السلسلة. افعل ما تحب دون شعور بالذنب.";col=REST;}else if(isThursday(c)){icon="review";title="يوم مراجعة الأسبوع";sub="مراجعة القرآن وبقية المجالات + تقييم الأسبوع + قرار واحد للأسبوع القادم.";col=PURPLE;}else{icon="rescue";title="نسخة الإنقاذ مفعلة";sub="اليوم اختصرناه إلى القرآن والطب وإغلاق اليوم. لا تعويض ولا جلد للذات.";col=ORANGE;}rr.addView(new AppIconView(this,icon,col),new LinearLayout.LayoutParams(dp(43),dp(43)));LinearLayout t=new LinearLayout(this);t.setOrientation(LinearLayout.VERTICAL);t.setPadding(dp(8),0,0,0);t.addView(text(title,12,TEXT,true));t.addView(text(sub,8,MUTED,false));rr.addView(t,new LinearLayout.LayoutParams(0,-2,1));b.addView(rr);}

    private void addNowCard(LinearLayout r){LinearLayout b=card();b.setPadding(dp(10),dp(9),dp(10),dp(9));add(r,b,8);LinearLayout head=row();head.addView(text("الآن",13,TEXT,true),new LinearLayout.LayoutParams(0,-2,1));String active=prefs.getString("active_task_"+todayKey,"");if(!active.isEmpty())head.addView(pill("قيد التنفيذ",GREEN));b.addView(head);if(isFriday(Calendar.getInstance())){LinearLayout rr=row();rr.addView(new AppIconView(this,"rest",REST),new LinearLayout.LayoutParams(dp(46),dp(46)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(8),0,0,0);tx.addView(text("راحة الجمعة",13,TEXT,true));tx.addView(text("زيارة، لعبة، قراءة، نوم، خروج أو أي شيء مباح تحبه — بلا نقاط مطلوبة.",8,MUTED,false));rr.addView(tx,new LinearLayout.LayoutParams(0,-2,1));b.addView(rr);return;}Task cur=currentTask();if(cur==null){b.addView(emptyState("check","لا توجد مهمة في هذه اللحظة","ابدأ بالمهمة التالية عندما يحين وقتها."));return;}LinearLayout rr=row();int c=colorFor(cur.domain);rr.addView(new AppIconView(this,cur.icon,c),new LinearLayout.LayoutParams(dp(46),dp(46)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(8),0,0,0);tx.addView(text(cur.title,12,TEXT,true));tx.addView(text(time(displayStart(cur))+" – "+time(displayEnd(cur))+"  •  "+cur.tier,8,MUTED,false));rr.addView(tx,new LinearLayout.LayoutParams(0,-2,1));Button go=smallButton(active.equals(cur.id)?"فتح":"ابدأ",GREEN);rr.addView(go,new LinearLayout.LayoutParams(dp(62),dp(34)));go.setOnClickListener(v->showTaskDialog(cur));b.addView(rr);Task nx=nextTaskAfter(cur);if(nx!=null){TextView n=text("بعدها: "+nx.title,8,MUTED,false);n.setPadding(0,dp(6),0,0);b.addView(n);}}

    private void addMatchCard(LinearLayout r,boolean large){String used=matchDateThisWeek();boolean usedThis=!used.isEmpty();LinearLayout b=card();b.setPadding(dp(10),dp(9),dp(10),dp(9));add(r,b,large?6:7);LinearLayout rr=row();rr.addView(new AppIconView(this,"football",usedThis?MUTED:GREEN),new LinearLayout.LayoutParams(dp(43),dp(43)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(8),0,0,0);tx.addView(text("بطاقة المباراة الأسبوعية",11,TEXT,true));tx.addView(text(usedThis?"استُخدمت هذا الأسبوع. تتجدد يوم السبت.":"مرة واحدة هذا الأسبوع: تلغي كل مهام ما بعد العشاء وتستبدلها بالمباراة.",8,MUTED,false));rr.addView(tx,new LinearLayout.LayoutParams(0,-2,1));TextView btn=pill(usedThis?"مستخدمة":"استخدم الليلة",usedThis?MUTED:GREEN);rr.addView(btn);b.addView(rr);if(!usedThis){View.OnClickListener l=v->confirmMatchUse();btn.setOnClickListener(l);b.setOnClickListener(l);}}

    private void confirmMatchUse(){new AlertDialog.Builder(this).setTitle("استخدام بطاقة المباراة؟").setMessage("ستُستخدم بطاقة هذا الأسبوع لليوم، وتُلغى مهام ما بعد العشاء وتظهر المباراة بدلًا منها. لا يمكن استخدامها مرة ثانية حتى السبت القادم.").setNegativeButton("إلغاء",null).setPositiveButton("استخدمها",(d,w)->{prefs.edit().putString("match_week_"+weekId(Calendar.getInstance()),todayKey).apply();Toast.makeText(this,"تم تفعيل ليلة المباراة",Toast.LENGTH_SHORT).show();render();}).show();}

