    private void addGoalCard(LinearLayout r){if(isFriday(Calendar.getInstance()))return;LinearLayout goal=card();goal.setPadding(dp(11),dp(10),dp(11),dp(9));add(r,goal,8);LinearLayout gh=row();gh.addView(new AppIconView(this,isThursday(Calendar.getInstance())?"review":"target",isThursday(Calendar.getInstance())?PURPLE:GREEN),new LinearLayout.LayoutParams(dp(43),dp(43)));LinearLayout gt=new LinearLayout(this);gt.setOrientation(LinearLayout.VERTICAL);gt.setPadding(dp(8),0,0,0);gt.addView(text(isThursday(Calendar.getInstance())?"هدف الخميس":"هدف اليوم",15,TEXT,true));gt.addView(text(isThursday(Calendar.getInstance())?"إكمال مراجعة القرآن + التقييم + ٣ مراجعات مجالات":"النجاح = إكمال ٤ من ٥ مؤشرات أساسية",9,MUTED,false));gh.addView(gt,new LinearLayout.LayoutParams(0,-2,1));goal.addView(gh);if(isThursday(Calendar.getInstance())){int done=thursdayCoreDone();LinearLayout cr=new LinearLayout(this);cr.setOrientation(LinearLayout.HORIZONTAL);cr.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);cr.setPadding(0,dp(8),0,dp(6));addCoreDot(cr,"قرآن",done("thu_quran"),GREEN);addCoreDot(cr,"طب",done("thu_medicine"),CYAN);addCoreDot(cr,"English",done("thu_english"),BLUE);addCoreDot(cr,"عمل",done("thu_work"),ORANGE);addCoreDot(cr,"تقييم",done("thu_review"),PURPLE);goal.addView(cr);goal.addView(progress(done,5,PURPLE,5));}else{int core=coreDoneToday();LinearLayout cr=new LinearLayout(this);cr.setOrientation(LinearLayout.HORIZONTAL);cr.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);cr.setPadding(0,dp(8),0,dp(6));addCoreDot(cr,"قرآن",coreDone("quran"),GREEN);addCoreDot(cr,"طب",coreDone("medicine"),CYAN);addCoreDot(cr,"English",coreDone("english"),BLUE);addCoreDot(cr,"عمل",coreDone("work"),ORANGE);addCoreDot(cr,"انضباط",coreDone("close"),Color.rgb(100,112,125));goal.addView(cr);goal.addView(progress(core,5,GREEN,5));if(core>=4)goal.addView(center(core==5?"✓ يوم متكامل + رصيد إضافي":"✓ اليوم ناجح",9,GREEN,true));}}

    private void addRescueCard(LinearLayout r){LinearLayout b=card();b.setPadding(dp(10),dp(9),dp(10),dp(9));add(r,b,8);LinearLayout rr=row();rr.addView(new AppIconView(this,"rescue",ORANGE),new LinearLayout.LayoutParams(dp(43),dp(43)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(8),0,dp(5),0);tx.addView(text("اليوم خرج عن الخطة؟",11,TEXT,true));tx.addView(text("فعّل نسخة الإنقاذ: قرآن ١٥ د + طب ٢٥ د + إغلاق اليوم. هذا أفضل من ترك اليوم كله.",8,MUTED,false));rr.addView(tx,new LinearLayout.LayoutParams(0,-2,1));TextView use=pill("نسخة الإنقاذ",ORANGE);rr.addView(use);b.addView(rr);View.OnClickListener l=v->new AlertDialog.Builder(this).setTitle("تفعيل نسخة الإنقاذ؟").setMessage("ستُختصر بقية مهام اليوم إلى ثلاث مهام فقط. لا تستخدمها لتعويض الكمال، بل للعودة للمسار.").setNegativeButton("إلغاء",null).setPositiveButton("فعّل",(d,w)->{prefs.edit().putBoolean("rescue_"+todayKey,true).apply();render();}).show();use.setOnClickListener(l);b.setOnClickListener(l);}

    private void addStreakCard(LinearLayout r){LinearLayout b=card();b.setPadding(dp(11),dp(9),dp(11),dp(8));add(r,b,8);LinearLayout sh=row();LinearLayout st=new LinearLayout(this);st.setOrientation(LinearLayout.VERTICAL);st.addView(text("سلسلة أيام العمل",11,TEXT,true));st.addView(text(ar(streak())+" يوم ناجح",15,TEXT,true));sh.addView(st,new LinearLayout.LayoutParams(0,-2,1));sh.addView(new FlameStrip(this,Math.min(7,streak())),new LinearLayout.LayoutParams(dp(145),dp(42)));b.addView(sh);b.addView(center("الجمعة لا تكسر السلسلة، لأنها راحة مقصودة وليست فشلًا.",8,GREEN,true));}

    private View tasksPage(){ScrollView s=scroll();LinearLayout r=root(s);r.addView(topBar("المهام","more","filter"));r.addView(weekStrip());addDayModeBanner(r);if(isFriday(Calendar.getInstance())){addFridayPage(r);if(undoTaskId!=null&&System.currentTimeMillis()<undoUntil)addUndoBar(r);gap(r,18);return s;}addMatchCard(r,true);HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout chips=new LinearLayout(this);chips.setOrientation(LinearLayout.HORIZONTAL);chips.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);chips.setPadding(0,dp(7),0,dp(3));String[] fs={"الكل","قرآن","طب","إنجليزية","عمل","صحة","أسرة","LeapAhead"};for(String f:fs){TextView c=filterChip(f,f.equals(taskFilter));chips.addView(c);c.setOnClickListener(v->{taskFilter=f;prefs.edit().putString("v16_filter",f).apply();render();});}hs.addView(chips);r.addView(hs,new LinearLayout.LayoutParams(-1,dp(46)));addTaskGroups(r);addLaterInbox(r);Button add=primaryButton("+  إضافة مهمة مخصصة");LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(47));bp.setMargins(0,dp(11),0,dp(18));r.addView(add,bp);add.setOnClickListener(v->startActivity(new Intent(this,PlannerCenterActivity.class)));if(undoTaskId!=null&&System.currentTimeMillis()<undoUntil)addUndoBar(r);return s;}

    private void addFridayPage(LinearLayout r){LinearLayout hero=new LinearLayout(this);hero.setOrientation(LinearLayout.VERTICAL);hero.setGravity(Gravity.CENTER);hero.setPadding(dp(14),dp(18),dp(14),dp(18));hero.setBackground(round(Color.rgb(234,246,239),18,Color.rgb(203,231,214)));add(r,hero,8);hero.addView(new RewardArtView(this,"rest",REST),new LinearLayout.LayoutParams(dp(68),dp(68)));hero.addView(center("الجمعة: راحة بلا ذنب",17,TEXT,true));hero.addView(center("لا توجد نسبة مطلوبة، لا مهام متأخرة، ولا تحتاج شراء الراحة بالنقاط.",9,MUTED,false));hero.addView(center("يمكنك: زيارة الأهل • لعب • أنمي • قراءة • خروج • نوم • استكشاف حر",9,REST,true));r.addView(sectionHeader("اختياري فقط","لا يحسب عليك",null));LinearLayout opts=card();opts.setPadding(dp(11),dp(8),dp(11),dp(8));add(r,opts,3);opts.addView(rule("ورد قرآن إذا رغبت — بلا هدف عددي."));opts.addView(rule("استماع إنجليزي ممتع إذا جاءك مزاج."));opts.addView(rule("أي نشاط اجتماعي أو عائلي تحبه."));opts.addView(rule("لا مراجعة أسبوعية اليوم؛ مكانها الخميس."));}

    private void addTaskGroups(LinearLayout r){List<Task> all=filteredTasks();Task cur=currentTask();r.addView(sectionHeader("الآن","",null));if(cur!=null&&matches(cur)&&!done(cur))addTaskCard(r,cur,false);else addEmptyCard(r,"clock","لا توجد مهمة الآن","انتقل للتالي دون استعجال.");List<Task> next=new ArrayList<>(),later=new ArrayList<>(),doneList=new ArrayList<>(),late=new ArrayList<>();int now=nowMin();for(Task t:all){if(cur!=null&&t.id.equals(cur.id))continue;if(done(t)){doneList.add(t);continue;}if(displayEnd(t)<now){late.add(t);continue;}if(next.size()<3)next.add(t);else later.add(t);}r.addView(sectionHeader("التالي",ar(next.size())+" مهام",null));for(Task t:next)addTaskCard(r,t,false);if(next.isEmpty())addEmptyCard(r,"check","لا شيء تالٍ الآن","ممتاز، لا تبحث عن عمل إضافي.");r.addView(sectionHeader("لاحقًا اليوم",laterExpanded?"إخفاء":""+ar(later.size()),v->{laterExpanded=!laterExpanded;render();}));if(laterExpanded){for(Task t:later)addTaskCard(r,t,false);}else if(!later.isEmpty())addCollapsedCard(r,"باقي "+ar(later.size())+" مهام لاحقًا",()->{laterExpanded=true;render();});r.addView(sectionHeader("مكتمل",completedExpanded?"إخفاء":ar(doneList.size()),v->{completedExpanded=!completedExpanded;render();}));if(completedExpanded){for(Task t:doneList)addTaskCard(r,t,false);}else if(!doneList.isEmpty())addCollapsedCard(r,ar(doneList.size())+" مهام مكتملة",()->{completedExpanded=true;render();});if(!late.isEmpty()){r.addView(sectionHeader("متأخر","لا تعوض الكل",null));for(Task t:late)addTaskCard(r,t,false);if(shouldOfferRescue()&&!rescueActiveToday())addRescueCard(r);}}

