    private void redeemReward(String title,int cost){if(prefs.getBoolean("reward_used_"+todayKey+"_"+title,false)){Toast.makeText(this,"استخدمت هذه المكافأة اليوم بالفعل",Toast.LENGTH_SHORT).show();return;}if(credits()<cost){Toast.makeText(this,"رصيدك لا يكفي بعد",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("استخدام المكافأة").setMessage(title+"\nسيتم خصم "+cost+" رصيد. عند انتهاء وقتها أغلقها ولا تمددها تلقائيًا.").setNegativeButton("إلغاء",null).setPositiveButton("استخدمها",(d,w)->{prefs.edit().putInt("reward_credits",credits()-cost).putBoolean("reward_used_"+todayKey+"_"+title,true).apply();Toast.makeText(this,"استمتع بها ثم عد لمسارك",Toast.LENGTH_LONG).show();render();}).show();}

