    private String exportPrefs(){try{JSONObject out=new JSONObject();for(Map.Entry<String,?>e:prefs.getAll().entrySet()){Object v=e.getValue();JSONObject item=new JSONObject();if(v instanceof Boolean){item.put("t","b");item.put("v",v);}else if(v instanceof Integer){item.put("t","i");item.put("v",v);}else if(v instanceof Long){item.put("t","l");item.put("v",v);}else if(v instanceof Float){item.put("t","f");item.put("v",v);}else{item.put("t","s");item.put("v",String.valueOf(v));}out.put(e.getKey(),item);}return out.toString();}catch(Exception e){return"{}";}}
    private boolean importPrefs(String raw){try{JSONObject o=new JSONObject(raw);SharedPreferences.Editor e=prefs.edit();JSONArray names=o.names();if(names==null)return false;for(int i=0;i<names.length();i++){String k=names.getString(i);JSONObject it=o.getJSONObject(k);String t=it.optString("t");switch(t){case"b":e.putBoolean(k,it.optBoolean("v"));break;case"i":e.putInt(k,it.optInt("v"));break;case"l":e.putLong(k,it.optLong("v"));break;case"f":e.putFloat(k,(float)it.optDouble("v"));break;default:e.putString(k,it.optString("v"));}}e.apply();return true;}catch(Exception ex){return false;}}

    private void addTaskCard(LinearLayout root,Task task,boolean compact){LinearLayout box=card();box.setPadding(dp(9),compact?dp(7):dp(8),dp(9),compact?dp(7):dp(8));add(root,box,compact?5:6);LinearLayout rr=row();int c=colorFor(task.domain);rr.addView(new AppIconView(this,task.icon,c),new LinearLayout.LayoutParams(dp(39),dp(39)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(8),0,dp(5),0);LinearLayout titleRow=row();titleRow.addView(text(task.title,compact?11:12,done(task)?MUTED:TEXT,true),new LinearLayout.LayoutParams(0,-2,1));titleRow.addView(tierPill(task.tier,c));tx.addView(titleRow);tx.addView(text(time(displayStart(task))+"  •  "+shortDomain(task.domain),8,MUTED,false));rr.addView(tx,new LinearLayout.LayoutParams(0,-2,1));CheckView chk=new CheckView(this,done(task));rr.addView(chk,new LinearLayout.LayoutParams(dp(27),dp(27)));box.addView(rr);box.setAlpha(0f);box.animate().alpha(1f).setDuration(130).start();box.setOnClickListener(v->showTaskDialog(task));chk.setOnClickListener(v->{v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);setDone(task,!done(task));});}

    private void showTaskDialog(Task t){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);v.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);v.setPadding(dp(16),dp(8),dp(16),dp(4));LinearLayout h=row();h.addView(new AppIconView(this,t.icon,colorFor(t.domain)),new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout ht=new LinearLayout(this);ht.setOrientation(LinearLayout.VERTICAL);ht.setPadding(dp(9),0,0,0);ht.addView(text(t.title,15,TEXT,true));ht.addView(text(time(displayStart(t))+" – "+time(displayEnd(t))+" • "+shortDomain(t.domain)+" • "+t.tier,9,MUTED,false));h.addView(ht,new LinearLayout.LayoutParams(0,-2,1));v.addView(h);TextView obj=text("الهدف: "+t.objective,9,TEXT,false);obj.setPadding(0,dp(10),0,dp(10));v.addView(obj);Button start=primaryButton(prefs.getString("active_task_"+todayKey,"").equals(t.id)?"قيد التنفيذ":"ابدأ جلسة");v.addView(start,new LinearLayout.LayoutParams(-1,dp(44)));Button done=secondaryButton(done(t)?"إلغاء الإنجاز":"تم الإنجاز");LinearLayout.LayoutParams dp1=new LinearLayout.LayoutParams(-1,dp(42));dp1.setMargins(0,dp(6),0,0);v.addView(done,dp1);Button snooze=secondaryButton("تأجيل ١٥ دقيقة");LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(42));sp.setMargins(0,dp(6),0,0);v.addView(snooze,sp);AlertDialog dlg=new AlertDialog.Builder(this).setTitle("تفاصيل المهمة").setView(v).setNegativeButton("إغلاق",null).setNeutralButton("تعديل",(d,w)->startActivity(new Intent(this,PlannerCenterActivity.class))).create();start.setOnClickListener(x->{prefs.edit().putString("active_task_"+todayKey,t.id).putLong("active_started_"+todayKey,System.currentTimeMillis()).apply();Toast.makeText(this,"بدأت: "+t.title,Toast.LENGTH_SHORT).show();dlg.dismiss();render();});done.setOnClickListener(x->{setDone(t,!done(t));dlg.dismiss();});snooze.setOnClickListener(x->{int n=prefs.getInt("postpone_"+todayKey+"_"+t.id,0)+15;prefs.edit().putInt("postpone_"+todayKey+"_"+t.id,n).apply();Toast.makeText(this,"تم التأجيل ١٥ دقيقة",Toast.LENGTH_SHORT).show();dlg.dismiss();render();});dlg.show();}

    private View weekStrip(){LinearLayout strip=new LinearLayout(this);strip.setOrientation(LinearLayout.HORIZONTAL);strip.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);strip.setPadding(0,dp(4),0,dp(2));Calendar c=saturdayStart(Calendar.getInstance());String[] names={"سبت","أحد","اثن","ثلا","أربع","خميس","جمعة"};for(int i=0;i<7;i++){Calendar d=(Calendar)c.clone();d.add(Calendar.DAY_OF_MONTH,i);boolean now=dateKey(d).equals(todayKey);LinearLayout cell=new LinearLayout(this);cell.setOrientation(LinearLayout.VERTICAL);cell.setGravity(Gravity.CENTER);if(now)cell.setBackground(round(isFriday(d)?REST:isThursday(d)?PURPLE:GREEN,9));cell.addView(center(names[i],7,now?Color.WHITE:MUTED,false));cell.addView(center(ar(d.get(Calendar.DAY_OF_MONTH)),10,now?Color.WHITE:TEXT,true));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(43),1);p.setMargins(dp(2),0,dp(2),0);strip.addView(cell,p);}return strip;}

    private List<Task> tasksToday(){return tasksFor(Calendar.getInstance());}
