    private List<Task> applyMatch(List<Task>a,Calendar d){if(!isMatchDay(d))return a;List<Task>out=new ArrayList<>();for(Task t:a)if(t.start<1200)out.add(t);out.add(t("weekly_match",1200,1320,"المباراة الأسبوعية — لا مهام بعدها","الراحة",0,false,"football","اختياري","شاهد المباراة بلا شعور بالذنب؛ البطاقة استُهلكت لهذا الأسبوع."));return out;}
    private Task afternoon(int day){switch(day){case Calendar.SATURDAY:return t("family_talk",990,1020,"الأسرة + تدريب كلام قصير","الأسرة",8,true,"family","مساند","حديث قصير واضح دون محاولة إبهار أحد.");case Calendar.SUNDAY:return t("talk1",990,1020,"تدريب التواصل","التواصل",10,true,"talk","مساند","ابدأ محادثة أو تدرب على ترتيب الفكرة.");case Calendar.MONDAY:return t("family_friend",990,1020,"خدمة الأسرة + تفقد صديق","الأسرة",8,true,"family","مساند","فعل صغير واضح للأسرة أو صديق.");case Calendar.TUESDAY:return t("talk2",990,1020,"تدريب الكلام والحزم","التواصل",10,true,"talk","مساند","جملة رفض مهذبة أو طلب واضح.");default:return t("medicine_review",990,1050,"مراجعة قبول إضافية","الطب والقبول",12,true,"medicine","مساند","راجع أضعف نقطة من جلسة اليوم.");}}
    private void addCustom(List<Task>a,Calendar d){try{JSONArray arr=new JSONArray(prefs.getString("custom_tasks","[]"));for(int i=0;i<arr.length();i++){JSONObject o=arr.optJSONObject(i);if(o==null||!o.optBoolean("active",true))continue;int dy=o.optInt("day",0);if(dy!=0&&dy!=d.get(Calendar.DAY_OF_WEEK))continue;a.add(t(o.optString("id","custom_"+i),o.optInt("start",960),o.optInt("end",990),o.optString("title","مهمة مخصصة"),o.optString("domain","الانضباط"),o.optInt("points",10),o.optBoolean("required",false),"check",o.optBoolean("required",false)?"أساسي":"اختياري","مهمة مخصصة من مركز الجدول."));}}catch(Exception ignored){}}
    private Task t(String id,int s,int e,String title,String domain,int pts,boolean req,String icon,String tier,String objective){return new Task(id,s,e,title,domain,pts,req,icon,tier,objective);}
    private String englishTitle(int d){switch(d){case Calendar.SATURDAY:return"الإنجليزية: Vocabulary + Reading Explorer";case Calendar.SUNDAY:return"الإنجليزية: Vocabulary + Tactics";case Calendar.MONDAY:return"الإنجليزية: Vocabulary + Reading Explorer";case Calendar.TUESDAY:return"الإنجليزية: Vocabulary + Tactics";default:return"الإنجليزية: Vocabulary + Oxford Bookworms";}}
    private String medicineTitle(int d){switch(d){case Calendar.SATURDAY:return"القبول الطبي — أحياء";case Calendar.SUNDAY:return"القبول الطبي — كيمياء";case Calendar.MONDAY:return"القبول الطبي — أحياء + أسئلة";case Calendar.TUESDAY:return"القبول الطبي — كيمياء + مسائل";default:return"القبول الطبي — مراجعة مختلطة";}}
    private String workTitle(int d){switch(d){case Calendar.SATURDAY:case Calendar.SUNDAY:return"العمل: تطوير المشروع الحالي";case Calendar.MONDAY:case Calendar.TUESDAY:return"العمل: الوصول للسوق";default:return"العمل: دخل مباشر أو إغلاق مهمة مهمة";}}

    private List<Task> homeTasks(){List<Task> all=tasksToday(),out=new ArrayList<>();int now=nowMin();for(Task t:all){if(done(t)||t.id.equals("sleep2")||t.id.equals("lunch"))continue;if(displayEnd(t)>=now-20)out.add(t);if(out.size()>=5)break;}return out;}
    private List<Task> filteredTasks(){List<Task>x=new ArrayList<>();for(Task t:tasksToday())if(matches(t))x.add(t);return x;}
    private boolean matches(Task t){if("الكل".equals(taskFilter))return true;if("قرآن".equals(taskFilter))return t.domain.equals("القرآن");if("طب".equals(taskFilter))return t.domain.equals("الطب والقبول");if("إنجليزية".equals(taskFilter))return t.domain.equals("الإنجليزية");if("عمل".equals(taskFilter))return t.domain.equals("العمل والدخل");if("صحة".equals(taskFilter))return t.domain.equals("الصحة");if("أسرة".equals(taskFilter))return t.domain.equals("الأسرة");if("LeapAhead".equals(taskFilter))return t.id.startsWith("leap");return true;}
    private Task currentTask(){if(isFriday(Calendar.getInstance()))return null;String active=prefs.getString("active_task_"+todayKey,"");if(!active.isEmpty()){Task a=findToday(active);if(a!=null&&!done(a))return a;}int n=nowMin();for(Task t:tasksToday())if(!done(t)&&displayStart(t)<=n&&displayEnd(t)>=n)return t;for(Task t:tasksToday())if(!done(t)&&displayStart(t)>n)return t;return null;}
    private Task nextTaskAfter(Task cur){boolean found=false;for(Task t:tasksToday()){if(found&&!done(t))return t;if(t.id.equals(cur.id))found=true;}return null;}
    private Task findToday(String id){for(Task t:tasksToday())if(t.id.equals(id))return t;return null;}
    private int displayStart(Task t){return t.start+prefs.getInt("postpone_"+todayKey+"_"+t.id,0);}private int displayEnd(Task t){return t.end+prefs.getInt("postpone_"+todayKey+"_"+t.id,0);}private int nowMin(){Calendar c=Calendar.getInstance();return c.get(Calendar.HOUR_OF_DAY)*60+c.get(Calendar.MINUTE);}

    private boolean done(Task t){return prefs.getBoolean("reward_done_"+todayKey+"_"+t.id,false);}private boolean done(String id){Task t=findToday(id);return t!=null&&done(t);}private boolean doneOn(Task t,Calendar d){return prefs.getBoolean("reward_done_"+dateKey(d)+"_"+t.id,false);}
    private void setDone(Task t,boolean val){setDoneInternal(t,val,true);}
    private void setDoneInternal(Task t,boolean val,boolean allowUndo){boolean old=done(t);if(old==val)return;int delta=val?t.points:-t.points;String dk="reward_day_points_"+todayKey,dom="reward_domain_"+t.domain;SharedPreferences.Editor e=prefs.edit().putBoolean("reward_done_"+todayKey+"_"+t.id,val).putInt(dk,Math.max(0,prefs.getInt(dk,0)+delta));if(t.points>0&&!t.domain.equals("الراحة"))e.putInt(dom,Math.max(0,prefs.getInt(dom,0)+delta));if(val&&prefs.getString("active_task_"+todayKey,"").equals(t.id))e.remove("active_task_"+todayKey);e.apply();if(val&&allowUndo){undoTaskId=t.id;undoUntil=System.currentTimeMillis()+5000;handler.postDelayed(()->{if(System.currentTimeMillis()>=undoUntil){undoTaskId=null;}},5100);}syncCredits();Toast.makeText(this,val?"تم الإنجاز +"+t.points+" نقطة":"تم التراجع",Toast.LENGTH_SHORT).show();render();}

    private boolean coreDone(String id){for(Task t:tasksToday())if(t.id.equals(id)||("quran".equals(id)&&t.id.startsWith("quran")))if(done(t))return true;return false;}private int coreDoneToday(){if(isFriday(Calendar.getInstance()))return 5;if(isThursday(Calendar.getInstance()))return thursdayCoreDone();int n=0;if(coreDone("quran"))n++;if(coreDone("medicine"))n++;if(coreDone("english"))n++;if(coreDone("work"))n++;if(coreDone("close"))n++;return n;}private int thursdayCoreDone(){int n=0;if(done("thu_quran"))n++;if(done("thu_medicine"))n++;if(done("thu_english"))n++;if(done("thu_work"))n++;if(done("thu_review"))n++;return n;}private boolean coreSuccessToday(){return isFriday(Calendar.getInstance())||coreDoneToday()>=4;}
    private int countDoneToday(){int n=0;for(Task t:tasksToday())if(done(t))n++;return n;}private int overdueCount(){if(isFriday(Calendar.getInstance()))return 0;int n=0,now=nowMin();for(Task t:tasksToday())if(!done(t)&&displayEnd(t)<now)n++;return n;}private boolean shouldOfferRescue(){return !isThursday(Calendar.getInstance())&&!isFriday(Calendar.getInstance())&&(overdueCount()>=4||(nowMin()>1080&&coreDoneToday()<3));}private boolean rescueActiveToday(){return prefs.getBoolean("rescue_"+todayKey,false);}private boolean rescueFor(Calendar d){return prefs.getBoolean("rescue_"+dateKey(d),false);}

    private int dayPoints(Calendar c){return prefs.getInt("reward_day_points_"+dateKey(c),0);}private int dayTarget(Calendar c){int n=0;for(Task t:tasksFor(c))if(t.required)n+=t.points;return n;}private int dayRate(Calendar c){int t=dayTarget(c);return t==0?100:pct(dayPoints(c),t);}
    private int weekRate(){return weekRateAt(0);}private int weekRateAt(int back){Calendar st=saturdayStart(Calendar.getInstance());st.add(Calendar.DAY_OF_MONTH,-7*back);Calendar en=(Calendar)st.clone();en.add(Calendar.DAY_OF_MONTH,6);Calendar now=Calendar.getInstance();if(en.after(now))en=now;int p=0,t=0;while(!st.after(en)){int dt=dayTarget(st);if(dt>0){p+=dayPoints(st);t+=dt;}st.add(Calendar.DAY_OF_MONTH,1);}return pct(p,t);}private int monthRate(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int p=0,t=0;while(!c.after(now)){int dt=dayTarget(c);if(dt>0){p+=dayPoints(c);t+=dt;}c.add(Calendar.DAY_OF_MONTH,1);}return pct(p,t);}private int yearRate(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.MONTH,Calendar.JANUARY);c.set(Calendar.DAY_OF_MONTH,1);int p=0,t=0;while(!c.after(now)){int dt=dayTarget(c);if(dt>0){p+=dayPoints(c);t+=dt;}c.add(Calendar.DAY_OF_MONTH,1);}return pct(p,t);}
    private int monthCompleted(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){for(Task t:tasksFor(c))if(doneOn(t,c))n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}private int monthTaskCount(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){n+=tasksFor(c).size();c.add(Calendar.DAY_OF_MONTH,1);}return n;}private int monthDoneId(String part){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){for(Task t:tasksFor(c))if(t.id.contains(part)&&doneOn(t,c))n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}private int quranPagesThisMonth(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){for(Task t:tasksFor(c))if(t.id.startsWith("quran")&&doneOn(t,c))n+=2;if(prefs.getBoolean("reward_done_"+dateKey(c)+"_thu_quran",false))n+=8;c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private int focusMinutes(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int sum=0;while(!c.after(now)){String k=dateKey(c);for(Task t:tasksFor(c))if(prefs.getBoolean("reward_done_"+k+"_"+t.id,false)&&(t.domain.equals("الطب والقبول")||t.domain.equals("الإنجليزية")||t.domain.equals("العمل والدخل")||t.domain.equals("القرآن")||t.domain.equals("المعرفة والقراءة")))sum+=Math.max(0,t.end-t.start);c.add(Calendar.DAY_OF_MONTH,1);}return sum;}
    private int streak(){Calendar c=Calendar.getInstance();if(!isFriday(c)&&dayTarget(c)>0&&dayRate(c)<80)c.add(Calendar.DAY_OF_MONTH,-1);int n=0,guard=0;while(guard++<400){if(isFriday(c)){c.add(Calendar.DAY_OF_MONTH,-1);continue;}if(dayTarget(c)==0){c.add(Calendar.DAY_OF_MONTH,-1);continue;}if(dayRate(c)>=80){n++;c.add(Calendar.DAY_OF_MONTH,-1);}else break;}return n;}private int strongThisWeek(){Calendar c=saturdayStart(Calendar.getInstance()),now=Calendar.getInstance();int n=0;while(!c.after(now)){if(!isFriday(c)&&dayTarget(c)>0&&dayRate(c)>=80)n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}private int successfulDaysEver(){int n=0;Calendar c=Calendar.getInstance();for(int i=0;i<180;i++){if(!isFriday(c)&&dayTarget(c)>0&&dayRate(c)>=80)n++;c.add(Calendar.DAY_OF_MONTH,-1);}return n;}private int bounceBackCount(){Calendar c=Calendar.getInstance();for(int i=0;i<120;i++){if(isFriday(c)){c.add(Calendar.DAY_OF_MONTH,-1);continue;}Calendar prev=(Calendar)c.clone();prev.add(Calendar.DAY_OF_MONTH,-1);while(isFriday(prev))prev.add(Calendar.DAY_OF_MONTH,-1);if(dayRate(c)>=80&&dayTarget(prev)>0&&dayRate(prev)<60)return 1;c.add(Calendar.DAY_OF_MONTH,-1);}return 0;}private int countDoneIds(String part){int n=0;for(Map.Entry<String,?>e:prefs.getAll().entrySet())if(e.getKey().startsWith("reward_done_")&&e.getKey().contains(part)&&Boolean.TRUE.equals(e.getValue()))n++;return n;}
    private int weekDomainRate(String d){Calendar c=saturdayStart(Calendar.getInstance()),now=Calendar.getInstance();int e=0,t=0;while(!c.after(now)){for(Task x:tasksFor(c)){if(!x.domain.equals(d))continue;if(x.required)t+=x.points;if(doneOn(x,c))e+=x.points;}c.add(Calendar.DAY_OF_MONTH,1);}return pct(e,Math.max(1,t));}private String strongestDomain(){String best="القرآن";int v=-1;for(String d:domainColors.keySet()){if(d.equals("الراحة"))continue;int x=weekDomainRate(d);if(x>v){v=x;best=d;}}return best;}private String weakestDomain(){String best="العمل والدخل";int v=101;for(String d:domainColors.keySet()){if(d.equals("الراحة")||d.equals("الدين والمسجد"))continue;int x=weekDomainRate(d);if(x<v){v=x;best=d;}}return best;}

    private int domainPoints(String d){return prefs.getInt("reward_domain_"+d,0);}private int totalPoints(){int n=0;for(String d:domainColors.keySet())if(!d.equals("الراحة"))n+=domainPoints(d);return n;}private int credits(){return prefs.getInt("reward_credits",0);}private void syncCredits(){if(isFriday(Calendar.getInstance()))return;SharedPreferences.Editor e=prefs.edit();int add=0;String dk=todayKey;if(coreDoneToday()>=4&&!prefs.getBoolean("credit_core4_"+dk,false)){add+=5;e.putBoolean("credit_core4_"+dk,true);}if(coreDoneToday()==5&&!prefs.getBoolean("credit_core5_"+dk,false)){add+=3;e.putBoolean("credit_core5_"+dk,true);}String wk=weekId(Calendar.getInstance());if(strongThisWeek()>=5&&!prefs.getBoolean("credit_week5_"+wk,false)){add+=20;e.putBoolean("credit_week5_"+wk,true);}add+=awardOnce(e,"credit_medicine15",countDoneIds("medicine")>=15,20);add+=awardOnce(e,"credit_quran20",countDoneIds("quran")>=20,20);add+=awardOnce(e,"credit_streak7",streak()>=7,25);if(add>0)e.putInt("reward_credits",credits()+add);e.apply();}private int awardOnce(SharedPreferences.Editor e,String k,boolean ok,int amount){if(ok&&!prefs.getBoolean(k,false)){e.putBoolean(k,true);return amount;}return 0;}
    private int levelFor(int p){if(p>=8000)return 6;if(p>=5000)return 5;if(p>=3000)return 4;if(p>=1500)return 3;if(p>=600)return 2;return 1;}private int levelBase(int l){switch(l){case 2:return 600;case 3:return 1500;case 4:return 3000;case 5:return 5000;case 6:return 8000;default:return 0;}}private int levelNext(int l){switch(l){case 1:return 600;case 2:return 1500;case 3:return 3000;case 4:return 5000;case 5:return 8000;default:return 10000;}}private String levelName(int l){switch(l){case 2:return"منتظم";case 3:return"متقدم";case 4:return"راسخ";case 5:return"متقن";case 6:return"متمكن";default:return"البداية";}}private String levelMessage(int l){switch(l){case 1:return"ثبت الأساس قبل زيادة الحمل.";case 2:return"الاستمرار أهم من الكثرة.";case 3:return"تقدمك صار قابلًا للقياس.";case 4:return"العادة بدأت تصبح راسخة.";case 5:return"جودة التنفيذ الآن أهم من العدد.";default:return"حافظ على الاتزان ولا تضف أهدافًا لمجرد النقاط.";}}
    private String rankFor(int p){if(p>=1200)return"متمكن";if(p>=650)return"ذهبي";if(p>=300)return"فضي";return"برونزي";}private int rankBase(int p){if(p>=1200)return 1200;if(p>=650)return 650;if(p>=300)return 300;return 0;}private int rankNext(int p){if(p>=1200)return 1800;if(p>=650)return 1200;if(p>=300)return 650;return 300;}private String topBlocker(){String x=prefs.getString("weekly_blocker","");if(x==null||x.trim().isEmpty())x=prefs.getString("last_blocker","");return x==null||x.trim().isEmpty()?"لم يُسجّل بعد":x;}

    private boolean isThursday(Calendar c){return c.get(Calendar.DAY_OF_WEEK)==Calendar.THURSDAY;}private boolean isFriday(Calendar c){return c.get(Calendar.DAY_OF_WEEK)==Calendar.FRIDAY;}private String weekId(Calendar c){return dateKey(saturdayStart(c));}private String matchDateThisWeek(){return prefs.getString("match_week_"+weekId(Calendar.getInstance()),"");}private boolean isMatchDay(Calendar d){return dateKey(d).equals(prefs.getString("match_week_"+weekId(d),""));}
    private JSONArray laterItems(){try{return new JSONArray(prefs.getString("later_items","[]"));}catch(Exception e){return new JSONArray();}}

