    private LinearLayout root(ScrollView s){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);r.setPadding(dp(13),dp(3),dp(13),dp(8));s.addView(r,new ScrollView.LayoutParams(-1,-2));return r;}private ScrollView scroll(){ScrollView s=new ScrollView(this);s.setFillViewport(true);s.setClipToPadding(false);s.setBackgroundColor(BG);return s;}private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setBackground(round(CARD,15,BORDER));c.setElevation(dp(.7f));return c;}private void add(LinearLayout r,View v,int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(top),0,0);r.addView(v,p);}private void gap(LinearLayout r,int v){View x=new View(this);r.addView(x,new LinearLayout.LayoutParams(1,dp(v)));}private void divider(LinearLayout p){View v=new View(this);v.setBackgroundColor(BORDER);p.addView(v,new LinearLayout.LayoutParams(-1,dp(1)));}
    private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);t.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);t.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));t.setIncludeFontPadding(false);return t;}private TextView center(String s,int size,int color,boolean bold){TextView t=text(s,size,color,bold);t.setGravity(Gravity.CENTER);return t;}private View progress(int value,int max,int color,int height){FrameLayout f=new FrameLayout(this);f.setBackground(round(TRACK,height));int pc=max<=0?0:Math.max(0,Math.min(100,Math.round(value*100f/max)));View fill=new View(this);fill.setBackground(round(color,height));f.addView(fill,new FrameLayout.LayoutParams(0,dp(height)));f.post(()->{ViewGroup.LayoutParams p=fill.getLayoutParams();p.width=Math.round(f.getWidth()*pc/100f);p.height=dp(height);fill.setLayoutParams(p);});f.setMinimumHeight(dp(height));return f;}private GradientDrawable round(int c,int r){return round(c,r,c);}private GradientDrawable round(int c,int r,int stroke){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));if(stroke!=c)g.setStroke(dp(1),stroke);return g;}private int colorFor(String d){return domainColors.containsKey(d)?domainColors.get(d):GREEN;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}private int pct(int a,int b){return b<=0?0:Math.max(0,Math.min(100,Math.round(a*100f/b)));}
    private String dateKey(Calendar c){return new SimpleDateFormat("yyyyMMdd",Locale.US).format(c.getTime());}private Calendar saturdayStart(Calendar now){Calendar c=(Calendar)now.clone();while(c.get(Calendar.DAY_OF_WEEK)!=Calendar.SATURDAY)c.add(Calendar.DAY_OF_MONTH,-1);c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c;}private String time(int min){int h=(min/60)%24,m=min%60;String suf=h>=12?"م":"ص";int hh=h%12;if(hh==0)hh=12;return ar(hh)+":"+(m<10?"٠":"")+ar(m)+" "+suf;}private String formatMinutes(int min){if(min<60)return ar(min)+" د";int h=min/60,m=min%60;return ar(h)+"س"+(m>0?" "+ar(m)+"د":"");}private String shortDomain(String d){if(d==null)return"—";if(d.equals("الطب والقبول"))return"الطب";if(d.equals("العمل والدخل"))return"العمل";if(d.equals("المعرفة والقراءة"))return"القراءة";if(d.equals("الدين والمسجد"))return"المسجد";return d;}private String iconForDomain(String d){if(d.equals("القرآن"))return"quran";if(d.equals("الطب والقبول"))return"medicine";if(d.equals("الإنجليزية"))return"headphones";if(d.equals("العمل والدخل"))return"briefcase";if(d.equals("الصحة"))return"heart";if(d.equals("المعرفة والقراءة"))return"book";if(d.equals("التواصل"))return"talk";if(d.equals("الأسرة"))return"family";if(d.equals("الدين والمسجد"))return"mosque";if(d.equals("الراحة"))return"rest";return"star";}private String ar(int n){String s=String.valueOf(n),e="0123456789",a="٠١٢٣٤٥٦٧٨٩";for(int i=0;i<10;i++)s=s.replace(e.charAt(i),a.charAt(i));return s;}

    private static class ProfileAvatar extends View{private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);ProfileAvatar(Activity a){super(a);}@Override protected void onDraw(Canvas c){float s=Math.min(getWidth(),getHeight()),cx=getWidth()/2f,cy=getHeight()/2f;p.setShader(new LinearGradient(0,0,s,s,Color.rgb(219,240,227),Color.rgb(190,226,205),Shader.TileMode.CLAMP));c.drawCircle(cx,cy,s*.48f,p);p.setShader(null);p.setColor(Color.rgb(42,71,63));c.drawCircle(cx,cy-s*.10f,s*.13f,p);p.setColor(Color.rgb(54,91,79));c.drawRoundRect(new RectF(cx-s*.22f,cy+s*.04f,cx+s*.22f,cy+s*.36f),s*.17f,s*.17f,p);p.setColor(GREEN);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(s*.035f);c.drawCircle(cx,cy,s*.46f,p);p.setStyle(Paint.Style.FILL);}}
    private static class RingView extends View{private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private final int value,color;RingView(Activity a,int v,int c){super(a);value=v;color=c;}@Override protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),st=Math.max(3f,w*.065f);RectF r=new RectF(st,st,w-st,h-st);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(st);p.setStrokeCap(Paint.Cap.ROUND);p.setColor(TRACK);c.drawArc(r,-90,360,false,p);p.setColor(color);c.drawArc(r,-90,360*value/100f,false,p);p.setStyle(Paint.Style.FILL);p.setColor(TEXT);p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(w*.20f);Paint.FontMetrics fm=p.getFontMetrics();c.drawText(toArabic(value)+"٪",w/2f,h/2f-(fm.ascent+fm.descent)/2f,p);}}
    private static class CheckView extends View{private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private final boolean checked;CheckView(Activity a,boolean x){super(a);checked=x;setClickable(true);}@Override protected void onDraw(Canvas c){float s=Math.min(getWidth(),getHeight()),m=s*.17f;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(2f,s*.07f));p.setColor(checked?GREEN:Color.rgb(180,189,197));c.drawRoundRect(new RectF(m,m,s-m,s-m),s*.14f,s*.14f,p);if(checked){p.setStyle(Paint.Style.FILL);p.setColor(GREEN);c.drawRoundRect(new RectF(m,m,s-m,s-m),s*.14f,s*.14f,p);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeWidth(Math.max(2f,s*.07f));p.setColor(Color.WHITE);Path q=new Path();q.moveTo(s*.31f,s*.52f);q.lineTo(s*.44f,s*.64f);q.lineTo(s*.70f,s*.37f);c.drawPath(q,p);}}}
