    private class SixWeekBars extends View{private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);SixWeekBars(Activity a){super(a);}@Override protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),base=h*.78f,left=w*.07f,slot=w*.145f;int[] vals=new int[6];int best=0;for(int i=0;i<6;i++){vals[i]=weekRateAt(5-i);if(vals[i]>vals[best])best=i;}for(int i=0;i<6;i++){float x=left+i*slot,bh=Math.max(dp(4),(h*.57f)*vals[i]/100f);p.setColor(i==best?GREEN:Color.rgb(227,231,235));c.drawRoundRect(new RectF(x,base-bh,x+slot*.55f,base),dp(4),dp(4),p);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(dp(7));p.setColor(TEXT);c.drawText(toArabic(vals[i])+"%",x+slot*.275f,base-bh-dp(4),p);p.setTextSize(dp(7));p.setColor(MUTED);c.drawText("أسبوع "+toArabic(i+1),x+slot*.275f,base+dp(15),p);}}}
    private class TrendView extends View{private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);TrendView(Activity a){super(a);}@Override protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),l=w*.07f,r=w*.96f,t=h*.12f,b=h*.78f;p.setColor(Color.rgb(232,236,239));p.setStrokeWidth(dp(1));for(int i=0;i<=4;i++){float y=t+(b-t)*i/4f;c.drawLine(l,y,r,y,p);}Path path=new Path();int n=14;for(int i=0;i<n;i++){Calendar d=Calendar.getInstance();d.add(Calendar.DAY_OF_MONTH,-(n-1-i)*2);float x=l+(r-l)*i/(n-1f),y=b-(b-t)*dayRate(d)/100f;if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));p.setColor(GREEN);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);for(int i=0;i<n;i++){Calendar d=Calendar.getInstance();d.add(Calendar.DAY_OF_MONTH,-(n-1-i)*2);float x=l+(r-l)*i/(n-1f),y=b-(b-t)*dayRate(d)/100f;c.drawCircle(x,y,dp(2.2f),p);}p.setTextAlign(Paint.Align.CENTER);p.setTextSize(dp(7));p.setColor(MUTED);c.drawText("بداية الشهر",l,b+dp(15),p);c.drawText("اليوم",r,b+dp(15),p);}}
    private class DonutView extends View{private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);DonutView(Activity a){super(a);}@Override protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),s=Math.min(w,h)*.72f,cx=w/2f,cy=h*.48f,st=s*.16f;RectF rr=new RectF(cx-s/2,cy-s/2,cx+s/2,cy+s/2);String[] ds={"القرآن","الطب والقبول","الإنجليزية","العمل والدخل","المعرفة والقراءة"};int[] cols={GREEN,CYAN,BLUE,ORANGE,PURPLE};int sum=0;int[] vals=new int[ds.length];for(int i=0;i<ds.length;i++){vals[i]=Math.max(1,domainPoints(ds[i]));sum+=vals[i];}float a=-90;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(st);p.setStrokeCap(Paint.Cap.BUTT);for(int i=0;i<vals.length;i++){float sw=360f*vals[i]/sum;p.setColor(cols[i]);c.drawArc(rr,a,sw,false,p);a+=sw;}p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setColor(TEXT);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(dp(13));c.drawText(toArabic(monthCompleted()),cx,cy+dp(4),p);p.setTypeface(Typeface.DEFAULT);p.setTextSize(dp(7));p.setColor(MUTED);c.drawText("إجمالي",cx,cy+dp(15),p);}}

    private static void drawSymbol(Canvas c,Paint p,String type,int col,float cx,float cy,float size){p.setShader(null);p.setColor(col);p.setStrokeWidth(Math.max(2f,size*.09f));p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);p.setStyle(Paint.Style.STROKE);float r=size*.36f;RectF q=new RectF(cx-r,cy-r,cx+r,cy+r);Path x=new Path();switch(type){case"home":x.moveTo(cx-r,cy);x.lineTo(cx,cy-r*.8f);x.lineTo(cx+r,cy);x.lineTo(cx+r*.7f,cy+r);x.lineTo(cx-r*.7f,cy+r);x.close();c.drawPath(x,p);break;case"menu":case"more":p.setStyle(Paint.Style.FILL);for(int i=-1;i<=1;i++)c.drawCircle(cx+i*r*.65f,cy,size*.06f,p);break;case"bell":c.drawArc(q,205,130,false,p);c.drawLine(cx-r*.72f,cy+r*.15f,cx-r*.72f,cy+r*.55f,p);c.drawLine(cx-r*.72f,cy+r*.55f,cx+r*.72f,cy+r*.55f,p);break;case"filter":x.moveTo(cx-r,cy-r);x.lineTo(cx+r,cy-r);x.lineTo(cx+r*.2f,cy);x.lineTo(cx+r*.2f,cy+r);c.drawPath(x,p);break;case"check":c.drawRoundRect(q,r*.2f,r*.2f,p);x.moveTo(cx-r*.45f,cy);x.lineTo(cx-r*.08f,cy+r*.38f);x.lineTo(cx+r*.52f,cy-r*.4f);c.drawPath(x,p);break;case"stats":for(int i=0;i<3;i++){float xx=cx-r+i*r*.8f;c.drawLine(xx,cy+r,xx,cy+r*(.45f-i*.55f),p);}break;case"quran":case"book":c.drawRoundRect(new RectF(cx-r,cy-r*.72f,cx-r*.05f,cy+r*.72f),r*.1f,r*.1f,p);c.drawRoundRect(new RectF(cx+r*.05f,cy-r*.72f,cx+r,cy+r*.72f),r*.1f,r*.1f,p);c.drawLine(cx,cy-r*.58f,cx,cy+r*.78f,p);break;case"medicine":c.drawCircle(cx-r*.28f,cy-r*.40f,r*.28f,p);c.drawArc(new RectF(cx-r*.58f,cy-r*.05f,cx+r*.15f,cy+r*.70f),0,210,false,p);c.drawCircle(cx+r*.45f,cy+r*.32f,r*.16f,p);c.drawLine(cx+r*.15f,cy-r*.54f,cx+r*.62f,cy-r*.54f,p);c.drawLine(cx+r*.385f,cy-r*.77f,cx+r*.385f,cy-r*.31f,p);break;case"headphones":c.drawArc(q,195,150,false,p);c.drawRoundRect(new RectF(cx-r,cy,cx-r*.63f,cy+r*.65f),r*.12f,r*.12f,p);c.drawRoundRect(new RectF(cx+r*.63f,cy,cx+r,cy+r*.65f),r*.12f,r*.12f,p);break;case"briefcase":c.drawRoundRect(new RectF(cx-r,cy-r*.42f,cx+r,cy+r*.68f),r*.13f,r*.13f,p);c.drawRect(cx-r*.34f,cy-r*.73f,cx+r*.34f,cy-r*.42f,p);c.drawLine(cx-r,cy,cx+r,cy,p);break;case"heart":x.moveTo(cx,cy+r);x.cubicTo(cx-r*1.2f,cy+r*.15f,cx-r*.8f,cy-r,cx,cy-r*.2f);x.cubicTo(cx+r*.8f,cy-r,cx+r*1.2f,cy+r*.15f,cx,cy+r);c.drawPath(x,p);break;case"family":p.setStyle(Paint.Style.FILL);c.drawCircle(cx-r*.42f,cy-r*.28f,r*.20f,p);c.drawCircle(cx+r*.42f,cy-r*.28f,r*.20f,p);c.drawCircle(cx,cy-r*.45f,r*.23f,p);c.drawRoundRect(new RectF(cx-r*.78f,cy+r*.02f,cx+r*.78f,cy+r*.55f),r*.28f,r*.28f,p);break;case"talk":c.drawRoundRect(new RectF(cx-r,cy-r*.65f,cx+r*.72f,cy+r*.45f),r*.2f,r*.2f,p);x.moveTo(cx-r*.15f,cy+r*.45f);x.lineTo(cx-r*.55f,cy+r);x.lineTo(cx+r*.05f,cy+r*.45f);c.drawPath(x,p);break;case"mosque":c.drawLine(cx-r,cy+r,cx+r,cy+r,p);c.drawRoundRect(new RectF(cx-r*.62f,cy-r*.02f,cx+r*.62f,cy+r),r*.12f,r*.12f,p);c.drawArc(new RectF(cx-r*.47f,cy-r*.76f,cx+r*.47f,cy+r*.14f),180,180,false,p);c.drawLine(cx+r*.82f,cy-r*.65f,cx+r*.82f,cy+r,p);break;case"sleep":c.drawArc(q,78,252,false,p);break;case"meal":c.drawRoundRect(new RectF(cx-r*.75f,cy-r*.5f,cx+r*.75f,cy+r*.5f),r*.15f,r*.15f,p);break;case"calendar":case"review":c.drawRoundRect(q,r*.18f,r*.18f,p);c.drawLine(cx-r,cy-r*.25f,cx+r,cy-r*.25f,p);if(type.equals("review")){c.drawLine(cx-r*.55f,cy+r*.1f,cx-r*.2f,cy+r*.35f,p);c.drawLine(cx-r*.2f,cy+r*.35f,cx+r*.5f,cy-r*.05f,p);}break;case"target":c.drawCircle(cx,cy,r,p);c.drawCircle(cx,cy,r*.55f,p);c.drawCircle(cx,cy,r*.14f,p);break;case"gift":c.drawRect(cx-r,cy-r*.32f,cx+r,cy+r*.75f,p);c.drawLine(cx,cy-r*.32f,cx,cy+r*.75f,p);c.drawLine(cx-r,cy,cx+r,cy,p);break;case"medal":c.drawCircle(cx,cy-r*.12f,r*.58f,p);c.drawLine(cx-r*.24f,cy+r*.38f,cx-r*.42f,cy+r,p);c.drawLine(cx+r*.24f,cy+r*.38f,cx+r*.42f,cy+r,p);break;case"gamepad":c.drawRoundRect(new RectF(cx-r,cy-r*.45f,cx+r,cy+r*.55f),r*.35f,r*.35f,p);c.drawLine(cx-r*.55f,cy,cx-r*.15f,cy,p);c.drawLine(cx-r*.35f,cy-r*.2f,cx-r*.35f,cy+r*.2f,p);c.drawCircle(cx+r*.42f,cy-r*.10f,r*.08f,p);c.drawCircle(cx+r*.64f,cy+r*.13f,r*.08f,p);break;case"play":x.moveTo(cx-r*.35f,cy-r*.65f);x.lineTo(cx+r*.65f,cy);x.lineTo(cx-r*.35f,cy+r*.65f);x.close();c.drawPath(x,p);break;case"compass":c.drawCircle(cx,cy,r,p);x.moveTo(cx+r*.20f,cy-r*.55f);x.lineTo(cx-r*.12f,cy+r*.10f);x.lineTo(cx-r*.58f,cy+r*.35f);x.lineTo(cx-r*.20f,cy-r*.20f);x.close();c.drawPath(x,p);break;case"clock":case"focus":c.drawCircle(cx,cy,r,p);c.drawLine(cx,cy,cx,cy-r*.55f,p);c.drawLine(cx,cy,cx+r*.45f,cy+r*.20f,p);break;case"rocket":x.moveTo(cx,cy-r);x.cubicTo(cx+r*.55f,cy-r*.55f,cx+r*.55f,cy+r*.25f,cx,cy+r*.55f);x.cubicTo(cx-r*.55f,cy+r*.25f,cx-r*.55f,cy-r*.55f,cx,cy-r);x.close();c.drawPath(x,p);c.drawCircle(cx,cy-r*.22f,r*.15f,p);break;case"block":c.drawCircle(cx,cy,r,p);c.drawLine(cx-r*.7f,cy+r*.7f,cx+r*.7f,cy-r*.7f,p);break;case"football":c.drawCircle(cx,cy,r,p);p.setStyle(Paint.Style.FILL);c.drawCircle(cx,cy,r*.25f,p);p.setStyle(Paint.Style.STROKE);for(int i=0;i<5;i++){double a=-Math.PI/2+i*2*Math.PI/5;c.drawLine(cx+(float)Math.cos(a)*r*.25f,cy+(float)Math.sin(a)*r*.25f,cx+(float)Math.cos(a)*r*.76f,cy+(float)Math.sin(a)*r*.76f,p);}break;case"rest":c.drawArc(new RectF(cx-r,cy-r,cx+r,cy+r),40,260,false,p);c.drawCircle(cx+r*.55f,cy-r*.55f,r*.08f,p);break;case"rescue":c.drawCircle(cx,cy,r,p);c.drawLine(cx-r*.55f,cy,cx+r*.55f,cy,p);c.drawLine(cx,cy-r*.55f,cx,cy+r*.55f,p);break;case"later":c.drawRect(cx-r*.7f,cy-r*.55f,cx+r*.7f,cy+r*.55f,p);c.drawLine(cx-r*.45f,cy-r*.2f,cx+r*.35f,cy-r*.2f,p);c.drawLine(cx-r*.45f,cy+r*.15f,cx+r*.15f,cy+r*.15f,p);break;case"return":c.drawArc(q,30,280,false,p);x.moveTo(cx-r*.85f,cy-r*.25f);x.lineTo(cx-r*.95f,cy+r*.25f);x.lineTo(cx-r*.45f,cy+r*.12f);c.drawPath(x,p);break;case"info":c.drawCircle(cx,cy,r,p);c.drawLine(cx,cy-r*.05f,cx,cy+r*.52f,p);c.drawCircle(cx,cy-r*.48f,r*.05f,p);break;case"backup":case"restore":c.drawRoundRect(q,r*.15f,r*.15f,p);c.drawLine(cx,cy-r*.55f,cx,cy+r*.45f,p);if(type.equals("backup")){c.drawLine(cx,cy-r*.55f,cx-r*.3f,cy-r*.2f,p);c.drawLine(cx,cy-r*.55f,cx+r*.3f,cy-r*.2f,p);}else{c.drawLine(cx,cy+r*.45f,cx-r*.3f,cy+r*.1f,p);c.drawLine(cx,cy+r*.45f,cx+r*.3f,cy+r*.1f,p);}break;case"star":case"points":drawStar(c,p,cx,cy,r,col);break;default:c.drawCircle(cx,cy,r,p);}}
    private static void drawStar(Canvas c,Paint p,float cx,float cy,float r,int col){Path x=new Path();for(int i=0;i<10;i++){double a=-Math.PI/2+i*Math.PI/5;float rr=i%2==0?r:r*.45f,px=cx+(float)Math.cos(a)*rr,py=cy+(float)Math.sin(a)*rr;if(i==0)x.moveTo(px,py);else x.lineTo(px,py);}x.close();p.setStyle(Paint.Style.FILL);p.setColor(col);c.drawPath(x,p);}private static int lighten(int c,float a){return Color.rgb((int)(Color.red(c)+(255-Color.red(c))*a),(int)(Color.green(c)+(255-Color.green(c))*a),(int)(Color.blue(c)+(255-Color.blue(c))*a));}private static int darken(int c,float a){return Color.rgb((int)(Color.red(c)*(1-a)),(int)(Color.green(c)*(1-a)),(int)(Color.blue(c)*(1-a)));}private static String toArabic(int n){String s=String.valueOf(n),e="0123456789",a="٠١٢٣٤٥٦٧٨٩";for(int i=0;i<10;i++)s=s.replace(e.charAt(i),a.charAt(i));return s;}
